-- Chalaco: recreate public.page + 31 projects
DROP TABLE IF EXISTS public.page CASCADE;
CREATE TABLE public.page (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  name text,
  images jsonb,
  client text,
  category text,
  year text,
  description text,
  storage_folder text,
  link text
);

ALTER TABLE public.page ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Enable read access for all users" ON public.page;
CREATE POLICY "Enable read access for all users"
  ON public.page FOR SELECT USING (true);

GRANT SELECT ON public.page TO anon, authenticated;

INSERT INTO public.page (id, created_at, name, images, client, category, year, description, storage_folder, link) VALUES
  (1, '2025-04-04 16:57:47.339985+00', 'Lanzamiento: Camiseta 2022', NULL, 'Orense Sporting Club', 'Comerciales', '2022', 'Este comercial celebra el lanzamiento de una camiseta inspirada en la riqueza natural y productiva de la provincia de El Oro. A través de una narrativa visual vibrante, promovemos los principales recursos que caracterizan a esta región del Ecuador: la abundante producción de banano, la pujante industria camaronera y los majestuosos paisajes capturados mediante tomas aéreas.

Cada escena rinde homenaje a la conexión entre la tierra, el mar y su gente, reflejando con orgullo el valor de lo que representa El Oro. Esta camiseta no solo es una prenda, sino una declaración de identidad, cultura y pertenencia.', 'pagina1', 'https://www.youtube.com/watch?v=ta7UbEQSdXc'),
  (2, '2025-04-04 17:05:52.723286+00', 'Reorganization', NULL, 'Schubiger AG', 'Institucional', '2024', 'Edición, conformado y corrección de color del video institucional desarrollado para el proceso de rebranding de esta empresa internacional especializada en estudios ambientales, ubicada en Hergiswil, Suiza. El trabajo incluyó la optimización de la narrativa visual, balance de color, tratamiento de tonos y uniformización de la imagen para fortalecer la identidad renovada de la marca.', 'pagina2', 'https://www.youtube.com/watch?v=UiJtcVqEhDI'),
  (3, '2025-04-04 17:10:29.578771+00', 'Servicio al cliente', NULL, 'EMAPAG', 'Comerciales', '2022', 'Producción de un comercial de televisión para anunciar y socializar la apertura de la nueva oficina de EMAPAG, ubicada en el edificio Las Cámaras, en la ciudad de Guayaquil.

El comercial resalta la modernización de los espacios, la mejora en la atención al ciudadano y el compromiso de EMAPAG con brindar un servicio más eficiente, accesible y cercano a la comunidad guayaquileña.', 'pagina3', 'https://www.youtube.com/watch?v=IyOmje1I218'),
  (4, '2025-04-04 17:18:18.975233+00', 'Douglas Bastidas - "Ella se fue"', NULL, 'La real sociedad', 'Videoclips', '2024', 'Producción del video musical para el lanzamiento de la canción "Ella Se Fue", interpretada por Douglas Bastidas. Este proyecto rinde homenaje a Julio Jaramillo, uno de los artistas más emblemáticos en la historia musical del Ecuador.

El video combina una narrativa emocional con una estética visual que evoca la época dorada del bolero, destacando la influencia de Jaramillo en la música popular ecuatoriana y el legado que continúa inspirando a nuevas generaciones.', 'pagina4', 'https://www.youtube.com/watch?v=JpIoA1hZkmQ'),
  (5, '2025-04-04 17:21:49.533582+00', 'Lanzamiento: KATUK', NULL, 'Katuk', 'Comerciales', '2024', 'Producción audiovisual para el lanzamiento de Katuk, una innovadora app presentada en 2024 que reúne todo lo que necesitas en un solo lugar: desde oportunidades de empleo hasta compras en línea, servicios, entretenimiento y más.

El video muestra de manera creativa y dinámica cómo Katuk se integra en la vida cotidiana de las personas, facilitando sus actividades diarias y conectándolas con soluciones prácticas al alcance de un clic. Una experiencia digital diseñada para simplificar, resolver y acompañarte en cada momento.', 'pagina5', 'https://www.youtube.com/watch?v=u5Hy-QN80VY'),
  (6, '2025-04-04 17:27:09.83389+00', 'Video Promocional Malecón 2000', NULL, 'Avianca', 'Comerciales', '2022', 'Producción de un comercial para Avianca, enfocado en promocionar la ruta Bogotá–Guayaquil, con el objetivo de incentivar el turismo hacia esta vibrante ciudad ecuatoriana.

El comercial destaca al Malecón 2000 como uno de los principales atractivos turísticos de Guayaquil, mostrando sus espacios emblemáticos, actividades culturales, zonas de recreación y una variada oferta gastronómica. A través de una narrativa visual envolvente, se invita al público a descubrir todo lo que Guayaquil tiene para ofrecer, convirtiéndolo en un destino ideal para viajeros colombianos y latinoamericanos.', 'pagina6', 'https://www.youtube.com/watch?v=5UEmks6an3Y'),
  (7, '2025-04-04 17:29:20.268683+00', 'Lanzamiento: Pinturas Imperial', NULL, 'Pinturas Imperial', 'Institucional', '2022', 'Producción audiovisual para el rebranding de Pinturas Imperial, empresa ecuatoriana con trayectoria en el sector. Este proyecto tuvo como objetivo presentar su nueva imagen corporativa, reflejando una evolución hacia lo moderno sin perder la esencia que la caracteriza.

El video destaca sus renovadas instalaciones, procesos de producción con altos estándares de calidad, y al equipo humano que día a día aporta con dedicación y experiencia. Una narrativa visual que transmite solidez, innovación y el compromiso constante de Pinturas Imperial con sus clientes y con el país.

', 'pagina7', 'https://www.youtube.com/watch?v=4Vvcjkdwhp0'),
  (8, '2025-04-04 17:35:37.804491+00', 'Mar Rendón - "Antes de que me vaya"', NULL, 'La real sociedad', 'Videoclips', '2023', 'Producción del video musical de “Antes de que me vaya”, interpretada por la reconocida artista ecuatoriana Mar Rendón. El video busca evocar, a través de su propuesta audiovisual, los sentimientos de nostalgia, despedida y sensibilidad que transmite la canción.

Grabado en las instalaciones del Museo del Cacao, en Guayaquil, Ecuador, el entorno aporta una atmósfera íntima y simbólica, que resalta las emociones de la letra.', 'pagina8', 'https://www.youtube.com/watch?v=hfaSTOib2ic'),
  (9, '2025-04-04 17:58:31.806805+00', 'Aniversario 90 años - CS Emelec', NULL, 'Adidas Ecuador', 'Fotos', NULL, 'Serie de fotografías conmemorativas realizadas por los 90 años del Club Sport Emelec, uno de los equipos más emblemáticos del fútbol ecuatoriano. El proyecto recrea momentos únicos y memorables de su historia futbolística, rindiendo homenaje a su legado deportivo, su hinchada y su impacto cultural en el país.

Gracias a su propuesta visual potente y emotiva, este trabajo fue ampliamente reconocido a nivel nacional e internacional, obteniendo importantes galardones como:
– Yellow Awards
– Premios Cóndor de Oro
– Lux Awards
– Shortlist de los IPA (International Photography Awards)
– Bronce en One Eyeland
– Platino en los Muse Photography Awards (todos en 2019)
– Oro en los New York Photography Awards (2020)', 'pagina9', NULL),
  (10, '2025-04-04 18:04:11.236061+00', 'Lanzamiento: Cerveza El Puerto', NULL, 'El Puerto', 'Fotos', NULL, 'Producción de fotografía publicitaria para el lanzamiento oficial de El Puerto, una cerveza artesanal ecuatoriana que celebra el sabor auténtico y la identidad costera.', 'pagina10', NULL),
  (11, '2025-04-04 18:06:24.831209+00', 'Eléctricas 2022', NULL, 'Club Sport Emelec', 'Fotos', NULL, 'Producción audiovisual y fotográfica para la presentación oficial del equipo femenino del Club Sport Emelec en el año 2020, marcando un hito importante en la historia del club y del fútbol femenino en Ecuador.

Gracias a su enfoque creativo y su impacto social, esta producción fue reconocida internacionalmente con los siguientes premios en el año 2020:
– Mención de Honor en los WINA Awards
– Yellow Awards
– Shortlist en los International Photography Awards (IPA)
– Platino en los MUSE Photography Awards
– Oro en los New York Photography Awards', 'pagina11', NULL),
  (12, '2025-04-04 18:09:16.43375+00', 'Producción: Hillary', NULL, 'Hillary Resort', 'Fotos', NULL, 'Fotografia publicitaria para el Hillary Resort, realizado todos los años, mostrando sus vistas emblemáticas de la Provincia, sus instalaciones y diversas actividades.', 'pagina12', NULL),
  (13, '2025-04-04 19:06:06.947923+00', 'Presentación: Productos Oriental', NULL, 'Alimentos Oriental', 'Fotos', NULL, 'Producción fotográfica para el lanzamiento de una variedad de productos de la marca Alimentos Oriental, destacando su sabor, calidad y versatilidad en la cocina. Este proyecto aplicó técnicas de ingeniería visual para construir composiciones impactantes, atractivas y cuidadosamente diseñadas para campañas publicitarias en medios digitales e impresos.

Cada imagen fue elaborada con precisión, combinando iluminación, estilismo culinario y retoque profesional para resaltar las texturas, colores y personalidad de cada producto, logrando una comunicación visual efectiva y alineada con los valores de la marca.', 'pagina13', NULL),
  (14, '2025-04-04 19:09:02.02374+00', 'Agua micelar', NULL, 'Genomalab', 'Fotos', NULL, 'Producción de glamshot para la campaña publicitaria internacional del Agua Micelar de Genomalab, enfocada en resaltar la pureza, frescura y elegancia del producto dentro del mercado de cuidado personal.', 'pagina14', NULL),
  (15, '2025-04-04 19:14:25.542413+00', 'Campaña: Tropicalizado', NULL, 'Adidas Ecuador', 'Fotos', NULL, 'Producción de campaña visual para Adidas Ecuador, enfocada en la promoción de su línea de indumentaria y accesorios deportivos, en colaboración con referentes del fútbol ecuatoriano actual.

La campaña fotográfica mostro una narrativa dinámica y moderna, resaltando la identidad, el rendimiento y el estilo de la marca.', 'pagina15', NULL),
  (16, '2025-04-04 19:23:39.561835+00', 'Es tiempo de Zumar', NULL, 'ZUMAR', 'Institucional', '2021', 'Producción de video institucional para ZUMAR, con el objetivo de reflejar su cercanía con la comunidad y destacar los múltiples beneficios que brinda esta institución para mejorar la calidad de vida de las personas.

Resaltando el impacto positivo de ZUMAR en áreas como educación, salud, deporte y desarrollo social. A través de un lenguaje visual cálido y humano, el video transmite el compromiso de la institución con el bienestar colectivo, reforzando su papel como agente de cambio en la comunidad.', 'pagina16', 'https://www.youtube.com/watch?v=hz8i89wF28w'),
  (17, '2025-04-04 19:28:48.480706+00', 'Adidas Predator', NULL, 'Adidas Ecuador', 'Fotos', NULL, 'Producción de campaña fotográfica para Adidas Ecuador, con motivo del lanzamiento de los nuevos zapatos de fútbol Predator.

La campaña contó con la participación de dos referentes del fútbol ecuatoriano actual: Javier Burrai y Allen Obando, quienes encarnan el espíritu competitivo, la precisión y el talento que caracteriza a la nueva generación de jugadores.', 'pagina17', NULL),
  (18, '2025-04-04 19:35:30.628332+00', 'Memorias de sostenibilidad', NULL, 'Banco del Pacifico', 'Fotos', NULL, 'Producción fotográfica para la campaña institucional del Banco del Pacífico, enfocada en la graficación de la rendición de cuentas del año 2019.', 'pagina18', NULL),
  (19, '2025-04-04 19:42:32.406053+00', 'Habitaciones Hillary', NULL, 'Hillary Resort', 'Fotos', NULL, 'Fotografias para promoción de habitaciones del hillary resort.', 'pagina19', NULL),
  (20, '2025-04-04 19:47:28.845478+00', 'Retrato Chefs - Libro Raices 2019', NULL, 'Centro de Convenciones', 'Fotos', NULL, 'Producción de retratos fotográficos para el libro oficial de Raíces 2019, enfocados en los chefs participantes de las charlas magistrales del evento gastronómico más importante del Ecuador.

La serie buscó capturar la esencia, personalidad y legado de cada chef, destacando su vínculo con la cocina como forma de identidad cultural.', 'pagina20', NULL),
  (21, '2025-04-04 19:48:14.86254+00', 'Publicidad Ecotec 2020', NULL, 'Ecotec', 'Fotos', NULL, 'Fotografia publicitaria para la Universidad Ecotec en el año 2020.', 'pagina21', NULL),
  (22, '2025-04-04 19:57:13.093165+00', 'Maquinarias Lycan', NULL, 'Lycan', 'Fotos', NULL, 'Fotografia publicitaria para Lycan Ecuador, mostrando sus nuevas maquinarias con colaboración de jugadores de Club Sport emelec.', 'pagina22', NULL),
  (23, '2025-04-04 20:14:58.579296+00', 'Mar Rendón - "Antes de que me vaya"', NULL, 'La real sociedad', 'Fotos', NULL, 'Producción fotográfica para la portada del single "Antes de que me vaya" de la artista ecuatoriana Mar Rendón, realizada en las instalaciones del emblemático Museo del Cacao en Guayaquil, Ecuador.

La imagen evoca visualmente la sensibilidad y melancolía que transmite la canción, fusionando la estética contemporánea con un entorno cargado de historia y simbolismo. El resultado es una pieza visual poética y poderosa, que acompaña con fuerza narrativa el lanzamiento musical.

Premios y reconocimientos obtenidos en 2023 y 2024:

Shortlist – International Photography Awards (IPA)

Selección oficial – Lürzer''s Creative Archive (Período 2023–2024)

Shortlist – Siena Creative Awards 2024

Platino – Muse Photography Awards', 'pagina23', NULL),
  (24, '2025-04-04 20:16:08.839745+00', 'Video Institucional', NULL, 'Siemens', 'Institucional', '2025', 'Video Institucional para Siemens, instalaciones y tecnología 4.0 en Electrocables.', 'pagina24', 'https://www.youtube.com/watch?v=Xau0xMT97iM'),
  (25, '2025-04-04 20:17:53.156419+00', 'Lanzamiento: Camiseta 2021', NULL, 'Adidas Ecuador', 'Comerciales', '2021', 'Comercial oficial para el lanzamiento de la nueva camiseta del Club Sport Emelec, en el marco de su alianza estratégica con la red social TikTok.

El spot fue diseñado con una narrativa ágil y visualmente impactante, combinando elementos de identidad del club con tendencias propias del lenguaje digital. Convirtiéndose rápidamente en un contenido viral dentro de la plataforma TikTok y generando alto engagement entre los hinchas y usuarios de la red social.', 'pagina25', 'https://youtube.com/shorts/Z_8j_mEcNqc?si=VrN69v-Cy1tV97lQ'),
  (26, '2025-04-04 20:34:19.310321+00', 'Lanzamiento: Camiseta 2023', NULL, 'Adidas Ecuador', 'Comerciales', '2023', 'Producción del comercial oficial para el lanzamiento de la camiseta 2023 del Club Sport Emelec, una edición conmemorativa del campeonato nacional de 1988, año en que el equipo logró un triunfo histórico venciendo a su clásico rival en su nuevo estadio.

La campaña fusiona con maestría el estilo retro de aquella época dorada con un enfoque moderno y dinámico, reflejando el legado y la evolución del club. A través de una narrativa cargada de emoción, orgullo y memoria futbolera, el comercial celebra la historia azul y conecta con distintas generaciones de hinchas.', 'pagina26', 'https://www.youtube.com/watch?v=UjVcYMQIFVw'),
  (27, '2025-11-18 23:52:09.881232+00', 'Suit an Cofie', NULL, 'Sweet and Coffee', 'Comerciales', '2025', '.', 'pagina27', 'https://www.youtube.com/watch?v=7NGO-N1nK68'),
  (28, '2025-11-19 00:10:51.41947+00', 'Aquí estamos Asobanca', NULL, 'Asobanca', 'Comerciales', '2025', '.', 'pagina28', 'https://www.youtube.com/watch?v=dQXwTZimfMU'),
  (29, '2025-11-19 00:17:25.567399+00', 'You Kandú', NULL, 'Kandú', 'Comerciales', '2025', '.', 'pagina29', 'https://www.youtube.com/watch?v=hX6AVyUTO9Q'),
  (30, '2025-11-19 00:36:08.22473+00', 'Third Jersey CS Emelec 25/26', NULL, 'Adidas Ecuador', 'Fotos', '2025', 'Tercera equipación del Club Sport Emelec para la temporada 25/26', 'pagina30', NULL),
